31	// NewCustomer is a customer to add with CreateCustomers.
32	type NewCustomer struct {
33		Name                 string
34		Email                string
35		DefaultPaymentMethod string
36		Metadata             map[string]string
37	}
38	
39	// CreateCustomers adds customers to an organization, in order, all or none: every customer is checked, and its email
40	// address compared with the organization's customers and with the earlier customers of the batch (ignoring case), before
41	// any is added.
42	func (s *Store) CreateCustomers(orgID string, ins []NewCustomer, now time.Time) ([]Customer, error) {
43		s.mu.Lock()
44		defer s.mu.Unlock()
45		if _, ok := s.orgs[orgID]; !ok {
46			return nil, ErrNotFound
47		}
48		taken := map[string]bool{}
49		for _, c := range s.customers {
50			if c.OrgID == orgID {
51				taken[normEmail(c.Email)] = true
52			}
53		}
54		for _, in := range ins {
55			name, email := strings.TrimSpace(in.Name), strings.TrimSpace(in.Email)
56			if name == "" || !validEmail(email) {
57				return nil, invalid("a customer needs a name and a valid email address")
58			}
59			if in.DefaultPaymentMethod != "" && !strings.HasPrefix(in.DefaultPaymentMethod, "pm_") {
60				return nil, invalid("a payment method looks like pm_...")
61			}
62			if taken[normEmail(email)] {
63				return nil, ErrEmailTaken
64			}
65			taken[normEmail(email)] = true
66		}
67		out := make([]Customer, 0, len(ins))
68		for _, in := range ins {
69			c := Customer{
70				ID: s.newID("cus"), OrgID: orgID, Name: strings.TrimSpace(in.Name), Email: strings.TrimSpace(in.Email),
71				DefaultPaymentMethod: in.DefaultPaymentMethod, CreatedAt: now.UTC(),
72			}
73			if len(in.Metadata) > 0 {
74				c.Metadata = in.Metadata
75			}
76			c = copyCustomer(c)
77			s.customers[c.ID] = c
78			s.customersByEmail[normEmail(c.Email)] = c.ID
79			out = append(out, copyCustomer(c))
80		}
81		return out, nil
82	}
