133	// SearchCustomers returns an organization's customers whose name or email contains q, ignoring case, oldest first.
134	func (s *Store) SearchCustomers(orgID, q string) []Customer {
135		q = strings.ToLower(strings.TrimSpace(q))
136		out := []Customer{}
137		for _, c := range s.Customers(orgID) {
138			if strings.Contains(strings.ToLower(c.Name), q) || strings.Contains(strings.ToLower(c.Email), q) {
139				out = append(out, c)
140			}
141		}
142		return out
143	}
