145	// FindCustomerByEmail returns the organization's customer with this email address, ignoring case.
146	func (s *Store) FindCustomerByEmail(orgID, email string) (Customer, bool) {
147		s.mu.Lock()
148		defer s.mu.Unlock()
149		id, ok := s.customersByEmail[normEmail(email)]
150		if !ok {
151			return Customer{}, false
152		}
153		return copyCustomer(s.customers[id]), true
154	}
155	
156	// UpdateCustomer changes a customer with f, which may refuse with an error. The ID and organization cannot change.
157	func (s *Store) UpdateCustomer(orgID, id string, f func(*Customer) error) (Customer, error) {
158		s.mu.Lock()
159		defer s.mu.Unlock()
160		old, ok := s.customers[id]
161		if !ok || old.OrgID != orgID {
162			return Customer{}, ErrNotFound
163		}
164		c := copyCustomer(old)
165		if err := f(&c); err != nil {
166			return Customer{}, err
167		}
168		c.ID, c.OrgID, c.CreatedAt = old.ID, old.OrgID, old.CreatedAt
169		c.Name, c.Email = strings.TrimSpace(c.Name), strings.TrimSpace(c.Email)
170		if c.Name == "" || !validEmail(c.Email) {
171			return Customer{}, invalid("a customer needs a name and a valid email address")
172		}
173		if c.DefaultPaymentMethod != "" && !strings.HasPrefix(c.DefaultPaymentMethod, "pm_") {
174			return Customer{}, invalid("a payment method looks like pm_...")
175		}
176		if newKey := normEmail(c.Email); newKey != normEmail(old.Email) {
177			if other, ok := s.customersByEmail[newKey]; ok && s.customers[other].OrgID == orgID {
178				return Customer{}, ErrEmailTaken
179			}
180			delete(s.customersByEmail, normEmail(old.Email))
181			s.customersByEmail[newKey] = c.ID
182		}
183		s.customers[id] = c
184		return copyCustomer(c), nil
185	}
186	
187	// DeleteCustomer removes a customer.
188	func (s *Store) DeleteCustomer(orgID, id string) error {
189		s.mu.Lock()
190		defer s.mu.Unlock()
191		c, ok := s.customers[id]
192		if !ok || c.OrgID != orgID {
193			return ErrNotFound
194		}
195		delete(s.customers, id)
196		if s.customersByEmail[normEmail(c.Email)] == id {
197			delete(s.customersByEmail, normEmail(c.Email))
198		}
199		return nil
200	}
201	
202	func copyCustomer(c Customer) Customer {
203		if c.Metadata != nil {
204			m := make(map[string]string, len(c.Metadata))
205			for k, v := range c.Metadata {
206				m[k] = v
207			}
208			c.Metadata = m
209		}
210		return c
211	}
