213	func sortCustomers(cs []Customer) {
214		sort.Slice(cs, func(i, j int) bool {
215			if !cs[i].CreatedAt.Equal(cs[j].CreatedAt) {
216				return cs[i].CreatedAt.Before(cs[j].CreatedAt)
217			}
218			return cs[i].ID < cs[j].ID
219		})
